"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# Detailed context around each || true usage
$content = Get-Content "E:'"\\VPS\\reports\\owner-admin-cutover-final-20260814-recovery-v1-fl17\\lib\\common.sh\"
"'$lines = @(110, 112, 138, 188, 191)
foreach ($ln in $lines) {
  $idx = $ln - 1
  $start = [Math]::Max(0, $idx - 3)
  $end = [Math]::Min($content.Count - 1, $idx + 3)
  Write-Output "=== Context around line $ln ==="
  for ($i = $start; $i -le $end; $i++) {
    $lineNum = $i + 1
    $marker = if ($lineNum -eq $ln) { ">>" } else { "  " }
    Write-Output "$marker $lineNum | $($content[$i])"
  }
  Write-Output ""
}'

